import{_ as t}from"./chunks/BrowseHome.D-hlO_QA.js";import{_ as a,c as s,a2 as o,o as r}from"./chunks/framework.CoXjB5sU.js";const i="/assets/BrowseCommunityList.2HWV39Og.png",n="/assets/BrowseCommunityPage.YbMpAO6-.png",l="/assets/BrowseSearch.GmdFWZH5.png",c="/assets/BrowseSearchAuthor.Co5KKCZL.png",h="/assets/BrowseItemCalculation.gB4d57uA.png",g="/assets/BrowseCmlViewer.AUN9ohZk.png",p="/assets/BrowseProfile.DzYGNYVU.png",u="/assets/BrowseMyDspace.D43qe0NJ.png",S=JSON.parse('{"title":"Browse module walkthrough","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/usage/browse-module-walkthrough.md","filePath":"doc/guides/usage/browse-module-walkthrough.md"}'),m={name:"doc/guides/usage/browse-module-walkthrough.md"};function d(w,e,b,f,y,_){return r(),s("div",null,e[0]||(e[0]=[o('<h1 id="browse-module-walkthrough" tabindex="-1">Browse module walkthrough <a class="header-anchor" href="#browse-module-walkthrough" aria-label="Permalink to &quot;Browse module walkthrough&quot;">​</a></h1><p>The Browse module is the public face of ioChem-BD: a web portal where the datasets published from the Create module become discoverable, browsable and citable for everyone. It is built on the DSpace repository platform.</p><p><img src="'+t+'" alt="Browse module home page"></p><p>The home page combines:</p><ul><li>A banner describing the portal</li><li>The cards of the <strong>Communities in Browse</strong>, usually one per research group</li><li>The <strong>Recent Submissions</strong> section with the latest published items (hidden when there are none)</li></ul><p>The top navigation bar gives access to the main areas: the <strong>Browse</strong> logo (home page), the search icon, <strong>Explore</strong> (communities and indexes by author, date and title), <strong>Searcher</strong> (the search page), <strong>Statistics</strong> and <strong>Docs</strong>, the user menu and the <strong>Create</strong> shortcut.</p><h2 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h2><p>Most of the Browse module is public. Logging in with your ioChem-BD account (the same centralized account as Create) adds personal areas such as <strong>MyDSpace</strong> and your researcher profile. Click <strong>Log In</strong> in the user menu and use your regular credentials. On the first login you are asked to accept the End User Agreement.</p><h2 id="communities-and-collections" tabindex="-1">Communities and collections <a class="header-anchor" href="#communities-and-collections" aria-label="Permalink to &quot;Communities and collections&quot;">​</a></h2><p>Published data is organized in three levels:</p><ul><li><strong>Communities</strong>: one per research group, created by the administrator.</li><li><strong>Collections</strong>: one per published project.</li><li><strong>Items</strong>: one per published calculation, report or asset.</li></ul><p><img src="'+i+'" alt="List of communities"></p><p>Open a community to see its collections and the items inside.</p><p><img src="'+n+'" alt="Community page with its collections"></p><h2 id="searching-data" tabindex="-1">Searching data <a class="header-anchor" href="#searching-data" aria-label="Permalink to &quot;Searching data&quot;">​</a></h2><p>The <strong>Searcher</strong> page searches all public content. Queries can be refined with the chemistry-aware facets on the results page:</p><ul><li><em>Author</em>, <em>Date</em>, <em>Access type</em> and <em>Item Type</em></li><li><strong>Program</strong>: the computational chemistry package used</li><li><strong>Method(s)</strong>: DFT, CASSCF, CASPT2, ...</li><li><strong>Basis set</strong>, <strong>Energy</strong>, <strong>Solv.</strong>, <strong>Vibr.</strong>, <strong>Orb.</strong></li></ul><p><img src="'+l+'" alt="Search results with facets"></p><p>Results can be displayed as a grid or a list, and every facet narrows the query with a single click.</p><p><img src="'+c+'" alt="Search results narrowed by author"></p><h2 id="the-calculation-item-page" tabindex="-1">The calculation item page <a class="header-anchor" href="#the-calculation-item-page" aria-label="Permalink to &quot;The calculation item page&quot;">​</a></h2><p>Every published calculation has its own item page showing the metadata table, the file section and, when available, a 3D molecular structure preview.</p><p><img src="'+h+'" alt="Calculation item page"></p><p>The file section offers chemistry-specific actions:</p><ul><li><strong>View data</strong>: opens the full-page CML viewer with an interactive JSmol representation of the molecule or simulation cell.</li><li><strong>Download geometry</strong>: downloads the molecular geometry directly.</li></ul><p>The <strong>View data</strong> action opens the CML viewer page, where the structure can be rotated, zoomed and inspected with the usual JSmol controls.</p><p><img src="'+g+'" alt="CML viewer page"></p><h2 id="researcher-profiles" tabindex="-1">Researcher profiles <a class="header-anchor" href="#researcher-profiles" aria-label="Permalink to &quot;Researcher profiles&quot;">​</a></h2><p>Every ioChem-BD user gets a researcher profile page that groups their published items. Keep your profile complete — ORCID iD and institutional affiliation — from the <strong>Profile</strong> page after logging in; this improves researcher identification and makes the portal statistics more accurate.</p><p><img src="'+p+'" alt="Profile page"></p><h2 id="mydspace" tabindex="-1">MyDSpace <a class="header-anchor" href="#mydspace" aria-label="Permalink to &quot;MyDSpace&quot;">​</a></h2><p>After logging in, the <strong>MyDSpace</strong> area shows your own workspace: the items you have published or that are being processed, with quick access to their management.</p><p><img src="'+u+'" alt="MyDSpace area"></p><h2 id="statistics" tabindex="-1">Statistics <a class="header-anchor" href="#statistics" aria-label="Permalink to &quot;Statistics&quot;">​</a></h2><p>The <strong>Statistics</strong> section aggregates usage statistics of the portal: total visits, most viewed collections and items, and per-community usage over time.</p>',35)]))}const B=a(m,[["render",d]]);export{S as __pageData,B as default};
